--   wheat bread whole (Whole Wheat Bread, default piece): -fl_oz -l -pt -qt
--   wheat chex cereal (Wheat Chex Cereal, default cup): -fl_oz -ml -l -pt -qt
--   wheat flour whole (Whole Wheat Flour, default cup): -fl_oz -l -pt -qt
--   white basmati rice (White Basmati Rice, default cup): -fl_oz -l -pt -qt
--   white bread (White Bread, default piece): -fl_oz -l -pt -qt
--   white jasmine rice (White Jasmine Rice, default cup): -fl_oz -l -pt -qt
--   white mushroom (White Mushroom, default oz): -tsp -tbsp -fl_oz -l -pt -qt
--   white rice (White Rice, default cup): -fl_oz -l -pt -qt
--   white rice cooked (Cooked White Rice, default cup): -tsp -fl_oz -l -pt -qt
--   white rice flour (White Rice Flour, default cup): -fl_oz -l -pt -qt
--   white sorghum flour (White Sorghum Flour, default g): -fl_oz -l -pt -qt
--   white vinegar (White Vinegar, default cup): -fl_oz -l -pt -qt
--   wild rice (Wild Rice, default cup): -fl_oz -l -pt -qt
--   yellow bell pepper (Yellow Bell Pepper, default piece): -fl_oz -l -pt -qt -handful
--   yellow mustard (Yellow Mustard, default tbsp): -fl_oz -l -pt -qt
--   yellow squash (Yellow Squash, default piece): -fl_oz -l -pt -qt -handful
--   zucchini (Zucchini, default piece): -fl_oz -l -pt -qt -handful

-- The invariants. `supabase db reset` FAILS loudly on any of them, and
-- they are checks on the EXPORTED data now: the cloud rows are curated,
-- not derived, so the only thing that can still be wrong is that the
-- curation itself is dishonest.
do $$
declare violators text;
        missing text;
        n_rows int; n_complete int; n_measures int;
begin
  -- R1: a volume default_unit on a PER-GRAM row REQUIRES a density — a
  -- volume line on a density-less per-g ingredient can never compute
  -- macros, so the class must not silently return. A per-100-ml row is
  -- exempt: its volume family is native and needs no bridge. Fix it by
  -- filling an honest density on the row (in the app), flipping its
  -- default to a weight, or stating the label per 100 ml, then
  -- re-exporting.
  select string_agg(canonical_name || ' (' || default_unit || ')', ', ')
    into violators
  from ingredient
  where household_id = '00000000-0000-0000-0000-0000000000aa' and deleted_at is null
    and default_unit in ('ml', 'l', 'tsp', 'tbsp', 'fl_oz', 'cup', 'pt', 'qt')
    and macros_basis = 'g'
    and density_g_per_ml is null;
  if violators is not null then
    raise exception
      'seed_vocab R1: volume-default per-g rows with no density: %',
      violators;
  end if;

  -- R2: every stored density is a KITCHEN density. A number outside this
  -- band is a parse artefact or the wrong physical quantity (2.165 is
  -- crystal salt, not what a spoonful weighs).
  select string_agg(
           canonical_name || ' (' || density_g_per_ml || ')', ', ')
    into violators
  from ingredient
  where household_id = '00000000-0000-0000-0000-0000000000aa' and deleted_at is null
    and density_g_per_ml is not null
    and density_g_per_ml not between 0.03 and 2;
  if violators is not null then
    raise exception
      'seed_vocab R2: densities outside 0.03-2 g/ml: %',
      violators;
  end if;

  -- R3 (ADR-0015): `piece` is admitted by a WEIGHT, so the two halves of
  -- that rule are the two halves of this invariant.
  --
  -- (a) Every counted row says what one of it weighs. A piece-default
  --     row with no piece weight is a STRANDED default: it would offer a
  --     `piece` nothing can convert, total or shop.
  select string_agg(canonical_name, ', ') into violators
  from ingredient
  where household_id = '00000000-0000-0000-0000-0000000000aa' and deleted_at is null
    and default_unit = 'piece' and piece_basis_amount is null;
  if violators is not null then
    raise exception
      'seed_vocab R3a: piece-default rows with no piece weight: %',
      violators;
  end if;

  -- (b) …and nothing else admits `piece`. The curated lists above are
  --     explicit, so this is the check that stops a reseed offering a
  --     `piece` of a row nobody counts.
  select string_agg(canonical_name || ' (' || default_unit || ')', ', ')
    into violators
  from ingredient
  where household_id = '00000000-0000-0000-0000-0000000000aa' and deleted_at is null
    and default_unit <> 'piece' and allowed_units ? 'piece';
  if violators is not null then
    raise exception
      'seed_vocab R3b: rows admitting piece without a count default: %',
      violators;
  end if;

  -- …and every measure resolved to a live vocab row. A measure whose
  -- ingredient is not there seeds NOTHING and would do it silently, so
  -- name the match_text instead. raise, not ASSERT: plpgsql.check_asserts
  -- can be disabled, and this check must never be.
  select string_agg(distinct m.mt, ', ') into missing
  from (values
    ('active yeast dry'),
    ('almond'),
    ('apple'),
    ('apricot'),
    ('asparagus'),
    ('avocado'),
    ('baked bean canned'),
    ('banana'),
    ('basil'),
    ('bay leaf'),
    ('beet'),
    ('beyond hot italian style sausage'),
    ('black bean canned'),
    ('black eyed pea canned'),
    ('black rice'),
    ('blueberry'),
    ('bouillon paste'),
    ('brazil nut'),
    ('breaded vegan chicken nugget'),
    ('broccoli'),
    ('brussel sprout'),
    ('burger bun'),
    ('butternut squash'),
    ('cabbage'),
    ('cannellini bean canned'),
    ('cantaloupe'),
    ('carrot'),
    ('cauliflower'),
    ('celery'),
    ('cherry'),
    ('chickpea canned'),
    ('cilantro'),
    ('cinnamon stick'),
    ('coconut flake dried'),
    ('coconut milk canned'),
    ('corn'),
    ('corn tortilla'),
    ('cremini mushroom'),
    ('crispy onion'),
    ('cucumber'),
    ('dark red kidney bean canned'),
    ('date'),
    ('dijon mustard'),
    ('dill'),
    ('dill pickle'),
    ('earth balance butter'),
    ('edamame frozen'),
    ('eggplant'),
    ('english muffin'),
    ('enoki mushroom'),
    ('extra firm tofu'),
    ('fennel'),
    ('fig dried'),
    ('fire tomato canned roasted'),
    ('flour tortilla'),
    ('gala apple'),
    ('garlic'),
    ('ginger'),
    ('gold potato'),
    ('granny smith apple'),
    ('grapefruit'),
    ('great northern bean canned'),
    ('green bean'),
    ('green bean canned'),
    ('green bell pepper'),
    ('green grape'),
    ('green olive'),
    ('hazelnut'),
    ('iceberg lettuce'),
    ('instant yeast'),
    ('jalapeno'),
    ('king oyster mushroom'),
    ('kiwi'),
    ('kombu'),
    ('leek'),
    ('lemon'),
    ('lemon juice'),
    ('lentil canned'),
    ('light red kidney bean canned'),
    ('lime'),
    ('lime juice'),
    ('liquid amino'),
    ('liquid smoke'),
    ('mango'),
    ('mild garlic chili crisp'),
    ('mint'),
    ('multigrain bread'),
    ('napa cabbage'),
    ('navy bean canned'),
    ('nectarine'),
    ('nori'),
    ('oat milk lite'),
    ('oat whipped cream'),
    ('okra'),
    ('onion'),
    ('orange'),
    ('orange bell pepper'),
    ('orange juice'),
    ('oregano fresh'),
    ('oyster mushroom'),
    ('parsley'),
    ('parsnip'),
    ('pea frozen'),
    ('peach'),
    ('pineapple'),
    ('pinto bean canned'),
    ('pistachio'),
    ('plain oat yogurt'),
    ('plantain'),
    ('poblano pepper'),
    ('portobello mushroom'),
    ('radish'),
    ('raspberry'),
    ('red bell pepper'),
    ('red cabbage'),
    ('red chili fresh'),
    ('red delicious apple'),
    ('red grape'),
    ('red leaf lettuce'),
    ('red onion'),
    ('red potato'),
    ('red rice'),
    ('rhubarb'),
    ('romaine lettuce'),
    ('russet potato'),
    ('scallion'),
    ('serrano pepper'),
    ('shallot'),
    ('sherry vinegar'),
    ('shiitake mushroom'),
    ('silken tofu'),
    ('soft sandwich bread'),
    ('spinach'),
    ('sprouted multigrain bread'),
    ('star anise'),
    ('strawberry'),
    ('super firm tofu'),
    ('sweet potato'),
    ('tempeh'),
    ('thai basil'),
    ('tomato'),
    ('tomato canned'),
    ('tomato canned whole'),
    ('tomato paste'),
    ('tomato puree canned'),
    ('tomato sauce canned'),
    ('tostada shell'),
    ('turnip'),
    ('ume plum vinegar'),
    ('vegan cheddar'),
    ('vegan mayonnaise'),
    ('vegan mozzarella'),
    ('vegan parmesan'),
    ('vegan worcestershire sauce'),
    ('vegetable broth'),
    ('watermelon'),
    ('wheat bread whole'),
    ('wheat chex cereal'),
    ('white bread'),
    ('white mushroom'),
    ('yellow bell pepper'),
    ('yellow squash'),
    ('zucchini')
  ) as m(mt)
  where not exists (
    select 1 from ingredient i
    where i.household_id = '00000000-0000-0000-0000-0000000000aa'
      and i.deleted_at is null and i.match_text = m.mt
  );
  if missing is not null then
    raise exception
      'seed_vocab: no live vocab ingredient for measures of: %', missing;
  end if;

  select count(*), count(*) filter (where status = 'complete')
    into n_rows, n_complete
  from ingredient
  where household_id = '00000000-0000-0000-0000-0000000000aa' and deleted_at is null;
  select count(*) into n_measures from ingredient_measure
  where household_id = '00000000-0000-0000-0000-0000000000aa' and deleted_at is null;
  raise notice
    'seed_vocab: % template ingredients (% complete), % measures; R1 (volume default => density), R2 (kitchen density band) and R3 (every counted row weighed, and only counted rows admit piece) hold', n_rows, n_complete, n_measures;
end $$;

commit;
